import{_ as e,c as r,o as t,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"4、【蒙】 坎下艮上","description":"温公易说 - 4、【蒙】 坎下艮上","frontmatter":{"title":"4、【蒙】 坎下艮上","description":"温公易说 - 4、【蒙】 坎下艮上"},"headers":[],"relativePath":"zh/classics/wengong/005.md","filePath":"zh/classics/wengong/005.md"}'),h={name:"zh/classics/wengong/005.md"};function n(l,a,o,s,d,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_4、【蒙】-坎下艮上" tabindex="-1">4、【蒙】 坎下艮上 <a class="header-anchor" href="#_4、【蒙】-坎下艮上" aria-label="Permalink to “4、【蒙】 坎下艮上”">​</a></h1><p>需者，何待时而行之谓也；孚者，见信于人之谓也。夫信者，已之所为也；孚者，待人而后成者也。故夫需之道，利安而不利躁；修己以待人者也，非夫信义着明、道徳光大，则不能以亨也。居正待时，然后吉也；用邪求益，宜其凶也。需以涉难，难可济也；躁以涉川，沉可必也。</p><h3 id="彖曰-蒙山下有险-险而止-蒙亨以亨行时中也。匪我求童蒙-童蒙求我-志应也。初筮告以刚中也。再三渎渎则不告-渎蒙也。蒙以养正-圣功也。" tabindex="-1">彖曰：蒙山下有险，险而止，蒙亨以亨行时中也。匪我求童蒙，童蒙求我，志应也。初筮告以刚中也。再三渎渎则不告，渎蒙也。蒙以养正，圣功也。 <a class="header-anchor" href="#彖曰-蒙山下有险-险而止-蒙亨以亨行时中也。匪我求童蒙-童蒙求我-志应也。初筮告以刚中也。再三渎渎则不告-渎蒙也。蒙以养正-圣功也。" aria-label="Permalink to “彖曰：蒙山下有险，险而止，蒙亨以亨行时中也。匪我求童蒙，童蒙求我，志应也。初筮告以刚中也。再三渎渎则不告，渎蒙也。蒙以养正，圣功也。”">​</a></h3><p>蒙者何？百姓蚩蚩，莫知所之。圣人教之以道，然后晓然识其是非。故夫蒙者，教人之象也。匪我求童蒙，童蒙求我，孔子曰：&quot;不愤不启，不悱不发。&quot;夫人不求我而强教之，则志不应而言不从矣。故君子之教，道而弗牵，强而弗抑，开而弗达也。初筮告，再三渎，渎则不告，孔子曰：&quot;学而不思则罔，又曰举一隅不以三隅反则不复也。&quot;陆希声曰：&quot;初筮告，启其宗也。再三渎，以塞聪也。渎则不告，告乃成蒙也。&quot;夫鍜砺者工也，犀利者金也，植艺者圃也，坚实者木也。则工虽巧，不能持土以为兵，圃虽良，不能植谷而生梓也。故才者天也，不教则弃。教者人也，不才则悖。故人者，受才于天而受教于师。师者决其滞，发其蔽，抑其过，引其不及，以养进其天才而已。系辞曰：&quot;茍非其人，道不虚行。&quot;此之谓也。</p><h3 id="象曰-山下出泉-蒙。君子以果行育德。" tabindex="-1">象曰：山下出泉，蒙。君子以果行育德。 <a class="header-anchor" href="#象曰-山下出泉-蒙。君子以果行育德。" aria-label="Permalink to “象曰：山下出泉，蒙。君子以果行育德。”">​</a></h3><p>果行者，言其动也。育德者，言其静也。君子动果而静专，内明而外晦，此之谓蒙以养正也。</p><h3 id="初六-发蒙-利用刑人-用说桎梏-以往吝。-象曰-利用刑人-以正法也。" tabindex="-1">初六：发蒙，利用刑人，用说桎梏，以往吝。 象曰：利用刑人，以正法也。 <a class="header-anchor" href="#初六-发蒙-利用刑人-用说桎梏-以往吝。-象曰-利用刑人-以正法也。" aria-label="Permalink to “初六：发蒙，利用刑人，用说桎梏，以往吝。 象曰：利用刑人，以正法也。”">​</a></h3><h3 id="九二-包蒙-吉。纳妇-吉。子克家。-象曰-子克家-刚柔接也。" tabindex="-1">九二：包蒙，吉。纳妇，吉。子克家。 象曰：子克家，刚柔接也。 <a class="header-anchor" href="#九二-包蒙-吉。纳妇-吉。子克家。-象曰-子克家-刚柔接也。" aria-label="Permalink to “九二：包蒙，吉。纳妇，吉。子克家。 象曰：子克家，刚柔接也。”">​</a></h3><h3 id="六三-勿用取女-见金夫-不有躬-无攸利。-象曰-勿用取女-行不顺也。" tabindex="-1">六三：勿用取女，见金夫，不有躬，无攸利。 象曰：勿用取女，行不顺也。 <a class="header-anchor" href="#六三-勿用取女-见金夫-不有躬-无攸利。-象曰-勿用取女-行不顺也。" aria-label="Permalink to “六三：勿用取女，见金夫，不有躬，无攸利。 象曰：勿用取女，行不顺也。”">​</a></h3><h3 id="六四-困蒙-吝。-象曰-困蒙之吝-独逺实也。" tabindex="-1">六四：困蒙，吝。 象曰：困蒙之吝，独逺实也。 <a class="header-anchor" href="#六四-困蒙-吝。-象曰-困蒙之吝-独逺实也。" aria-label="Permalink to “六四：困蒙，吝。 象曰：困蒙之吝，独逺实也。”">​</a></h3><p>孔子曰：困而不学，民斯为下矣。圣人于是爻，将以戒夫不学者也。</p><h3 id="六五-童蒙-吉。-象曰-童蒙之吉-顺以巽也。" tabindex="-1">六五：童蒙，吉。 象曰：童蒙之吉，顺以巽也。 <a class="header-anchor" href="#六五-童蒙-吉。-象曰-童蒙之吉-顺以巽也。" aria-label="Permalink to “六五：童蒙，吉。 象曰：童蒙之吉，顺以巽也。”">​</a></h3><p>童蒙者何以吉也？得人而信使之也。昔齐桓公卫灵公之行，犬彘之所不为也。然而大则霸诸侯，小则有一国，其故何哉？有管仲仲叔圉祝鮀王孙贾为之辅也。二君者，天下之不肖君也，得贤人而信使之，犹且安其身而收其功，况明哲之君用忠良之臣者乎？</p><h3 id="上九-击蒙-不利为寇-利御寇。-象曰-利用御寇-上下顺也。" tabindex="-1">上九：击蒙，不利为寇，利御寇。 象曰：利用御寇，上下顺也。 <a class="header-anchor" href="#上九-击蒙-不利为寇-利御寇。-象曰-利用御寇-上下顺也。" aria-label="Permalink to “上九：击蒙，不利为寇，利御寇。 象曰：利用御寇，上下顺也。”">​</a></h3>',14)])])}const b=e(h,[["render",n]]);export{p as __pageData,b as default};
